package dev.veltraph.client.observation.unexpected;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static dev.veltraph.client.observation.unexpected.UnexpectedBehaviorMonitor.*;

final class PendingNativeInputOriginTest {
    final Context original=new Context(new Activation("farm",3,true),1,2,3);
    @Test void attackAndUseAreIncludedInStableNineKeyMask(){assertEquals(128,UnexpectedInputMask.ATTACK);assertEquals(256,UnexpectedInputMask.USE);assertEquals(511,UnexpectedInputMask.ALL);assertEquals(384,UnexpectedInputMask.expected(0,384,true));}
    @Test void attackAndUseNeverProvideMovementEvidence(){assertFalse(UnexpectedInputMask.movement(UnexpectedInputMask.ATTACK));assertFalse(UnexpectedInputMask.movement(UnexpectedInputMask.USE));assertFalse(UnexpectedInputMask.movement(384));assertTrue(UnexpectedInputMask.movement(385));}
    @Test void genuineChangedExpectedOutcomeIsConsumedExactlyOnce(){var p=new PendingNativeInputOrigin();p.record(original,0,128,true,100);assertTrue(p.consume(original,128,101));assertFalse(p.consume(original,128,102));}
    @Test void nativeReleaseCanAcknowledgeExactOwnOutcome(){var p=new PendingNativeInputOrigin();p.record(original,384,128,false,100);assertTrue(p.consume(original,256,101));}
    @Test void unrelatedSimultaneousBitsCannotBeAcknowledgedByOneButton(){var p=new PendingNativeInputOrigin();p.record(original,0,128,true,100);assertFalse(p.consume(original,384,101));assertFalse(p.consume(original,128,102));}
    @Test void callbackWithoutAnyAppliedDeltaCannotExplainADeferredOutsideChange(){var p=new PendingNativeInputOrigin();p.record(original,128,128,true,100);assertFalse(p.consume(original,128,101));}
    @Test void incompleteApplicationOfMultiBindingEventIsRefused(){var p=new PendingNativeInputOrigin();p.record(original,0,129,true,100);assertFalse(p.consume(original,128,101));}
    @Test void originalFiniteWindowIsAcceptedAndExpiredEventCannotBeReplayed(){var p=new PendingNativeInputOrigin();p.record(original,0,1,true,100);assertTrue(p.consume(original,1,300));p.record(original,0,1,true,100);assertFalse(p.consume(original,1,301));assertFalse(p.consume(original,1,300));}
    @Test void rollbackAndElapsedOverflowDoNotMintFreshOrigin(){var p=new PendingNativeInputOrigin();p.record(original,0,1,true,100);assertFalse(p.consume(original,1,99));p.record(original,0,1,true,Long.MIN_VALUE);assertFalse(p.consume(original,1,Long.MAX_VALUE));}
    @Test void ownerGenerationAndEveryNativeEpochRejectCrossContextOrigin(){for(var changed:new Context[]{new Context(new Activation("farm",4,true),1,2,3),new Context(new Activation("other",3,true),1,2,3),new Context(original.activation(),2,2,3),new Context(original.activation(),1,3,3),new Context(original.activation(),1,2,4)}){var p=new PendingNativeInputOrigin();p.record(original,0,256,true,100);assertFalse(p.consume(changed,256,101));assertFalse(p.consume(original,256,102));}}
    @Test void clearingIneligibleGuiOrCancelledHeadLeavesNoReceipt(){var p=new PendingNativeInputOrigin();p.record(original,0,256,true,100);p.clear();assertFalse(p.consume(original,256,101));}
    @Test void invalidInputMasksCannotBecomeNativeOutcome(){var p=new PendingNativeInputOrigin();assertThrows(IllegalArgumentException.class,()->p.record(original,0,1024,true,100));p.record(original,0,256,true,100);assertFalse(p.consume(original,1024,101));}
    @Test void unchangedObserverClassificationForUnexplainedActionRemainsUncertain(){var m=new UnexpectedBehaviorMonitor(f->{});m.context(original,100);var f=m.observe(new Observation(original,Kind.INPUT_STATE,Value.number(0),Value.number(256),101));assertEquals(Classification.UNCERTAIN,f.classification());assertFalse(f.evidence().contains(Cause.MOD_INTENT));}
    @Test void exactNativeMouseInputReceiptExplainsOnlyItsOutcomeWithoutHumanIdentity(){var m=new UnexpectedBehaviorMonitor(f->{});m.context(original,100);m.nativeReceipt(original,Kind.INPUT_STATE,Cause.NATIVE_MOUSE_EVENT,Value.number(128),0,100,200);var f=m.observe(new Observation(original,Kind.INPUT_STATE,Value.number(0),Value.number(128),101));assertEquals(Classification.EXPLAINED,f.classification());assertTrue(f.detail().contains("human identity is unknown"));assertEquals(Classification.UNCERTAIN,m.observe(new Observation(original,Kind.INPUT_STATE,Value.number(0),Value.number(128),102)).classification());}
    @Test void mouseInputReceiptDoesNotExplainUnrelatedSlotOrServerTeleport(){var m=new UnexpectedBehaviorMonitor(f->{});m.context(original,100);m.nativeReceipt(original,Kind.INPUT_STATE,Cause.NATIVE_MOUSE_EVENT,Value.number(128),0,100,200);assertEquals(Classification.UNEXPECTED,m.observe(new Observation(original,Kind.SELECTED_SLOT,Value.number(0),Value.number(2),101)).classification());m.signal(original,Kind.POSITION,Cause.SERVER_POSITION_PACKET,101,150);assertEquals(Classification.UNEXPECTED,m.observe(new Observation(original,Kind.POSITION,Value.position(0,0,0),Value.position(20,0,0),102)).classification());}
    @Test void retiredHeldHistoryCannotUsePriorMovementWindow(){for(var cause:new Cause[]{Cause.MOD_MOVEMENT_INPUT,Cause.NATIVE_KEY_EVENT,Cause.NATIVE_MOUSE_EVENT}){var m=new UnexpectedBehaviorMonitor(f->{});m.signal(original,Kind.POSITION,cause,100,150);m.retireHeldMovementSignals(cause);var finding=m.observe(new Observation(original,Kind.POSITION,Value.position(0,0,0),Value.position(1,0,0),101));assertFalse(finding.evidence().contains(cause));assertNotEquals(Classification.EXPLAINED,finding.classification());}}
    @Test void originRetirementPreservesFreshPhysicsAndExactInputOutcome(){var m=new UnexpectedBehaviorMonitor(f->{});m.signal(original,Kind.POSITION,Cause.NATIVE_KEY_EVENT,100,150);m.signal(original,Kind.POSITION,Cause.GRAVITY,100,150);m.nativeReceipt(original,Kind.INPUT_STATE,Cause.NATIVE_KEY_EVENT,Value.number(1),0,100,200);m.retireHeldMovementSignals(Cause.NATIVE_KEY_EVENT);var movement=m.observe(new Observation(original,Kind.POSITION,Value.position(0,0,0),Value.position(0,-1,0),101));assertTrue(movement.evidence().contains(Cause.GRAVITY));assertFalse(movement.evidence().contains(Cause.NATIVE_KEY_EVENT));assertEquals(Classification.EXPLAINED,m.observe(new Observation(original,Kind.INPUT_STATE,Value.number(0),Value.number(1),102)).classification());}
    @Test void retirementCannotDiscardUnrelatedServerOrNavigationEvidence(){var m=new UnexpectedBehaviorMonitor(f->{});assertThrows(IllegalArgumentException.class,()->m.retireHeldMovementSignals(Cause.SERVER_POSITION_PACKET));assertThrows(IllegalArgumentException.class,()->m.retireHeldMovementSignals(Cause.NATIVE_NAVIGATION_COMMAND));}
    @Test void failedAfterNormalPublicationCannotExplainLaterRawSameTarget(){var m=new UnexpectedBehaviorMonitor(f->{});m.intent(original,Kind.INPUT_STATE,Value.number(256),0,100,500,()->false);var f=m.observe(new Observation(original,Kind.INPUT_STATE,Value.number(0),Value.number(256),101));assertEquals(Classification.UNCERTAIN,f.classification());assertFalse(f.evidence().contains(Cause.MOD_INTENT));}
    @Test void confirmedAfterNormalHistoryIsRequiredAtObservation(){var m=new UnexpectedBehaviorMonitor(f->{});boolean[] current={false};m.intent(original,Kind.INPUT_STATE,Value.number(1),0,100,500,()->current[0]);current[0]=true;assertEquals(Classification.EXPLAINED,m.observe(new Observation(original,Kind.INPUT_STATE,Value.number(0),Value.number(1),101)).classification());m.intent(original,Kind.INPUT_STATE,Value.number(1),0,102,500,()->current[0]);current[0]=false;assertEquals(Classification.UNCERTAIN,m.observe(new Observation(original,Kind.INPUT_STATE,Value.number(0),Value.number(1),103)).classification());}
}
